function profileNotification(request, response, actorId) {
  if(request?.action!=='profile_edit' || response?.success!==true)return null;
  const p=response.profile,uid=Number(p?.user_id),version=Number(p?.profile_version);
  if(!Number.isSafeInteger(uid)||uid<=0||!Number.isSafeInteger(version)||version<=0||!Number.isSafeInteger(Number(actorId))||Number(actorId)<=0)return null;
  if(!['bmr','tdee','daily_calories','daily_protein','daily_fats','daily_carbs'].every(k=>Number.isFinite(Number(p[k]))&&Number(p[k])>0))return null;
  const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const n=v=>Math.round(Number(v)).toLocaleString('ru-RU');
  const goal={lose:'Похудение',lose_fast:'Быстрое похудение',maintain:'Поддержание веса',gain:'Набор массы',gain_fast:'Быстрый набор массы'}[p.goal]||p.goal_ru;
  const activity={'1.2':'минимальная','1.375':'лёгкая','1.55':'средняя','1.725':'высокая','1.9':'очень высокая'}[String(p.activity_level)]||String(p.activity_level);
  const text=`✅ <b>Профиль обновлён</b>

${esc(p.name)}, пересчитала дневную норму по новым параметрам:
${esc(p.age)} лет · ${esc(p.height)} см · ${esc(p.weight)} кг
Активность: ${esc(activity)}
Цель: ${esc(goal)}

<b>Расчёт по формуле Миффлина — Сан Жеора</b>
Основной обмен: ~${n(p.bmr)} ккал
С учётом активности: ~${n(p.tdee)} ккал в день

🎯 <b>Дневной ориентир: ${n(p.daily_calories)} ккал</b>
Белки: <b>${n(p.daily_protein)} г</b>
Жиры: <b>${n(p.daily_fats)} г</b>
Углеводы: <b>${n(p.daily_carbs)} г</b>${p.warning_message?'

'+esc(p.warning_message):''}`;
  return {user_id:uid,profile_version:version,actor_id:Number(actorId),message_text:text};
}

const data=$input.first().json;const request=$('Prepare Diary Query').first().json;const notification=profileNotification(request.request,data.response,request.actor_id);return notification?[{json:notification}]:[];

function prepareRecipeLibrary(actor,request,rows){
 if(!Number.isSafeInteger(actor)||actor<=0)throw Error('Invalid verified actor');
 const own=rows.filter(r=>Number(r.user_id)===actor&&Number.isSafeInteger(Number(r.id))&&Number(r.id)>0);
 if(request.action==='recipes'){
  const fields=['id','recipe_name','total_weight','total_calories','total_protein','total_fats','total_carbs','per_100g_calories','per_100g_protein','per_100g_fats','per_100g_carbs','ingredients','createdAt'];
  return {should_delete:false,response:{success:true,recipes:own.map(r=>Object.fromEntries(fields.map(k=>[k,r[k]??null]))).sort((a,b)=>Number(b.id)-Number(a.id))}};
 }
 if(request.action==='recipe_add')return {should_add:true,should_delete:false,actor_id:actor,request,snapshot:own.find(r=>Number(r.id)===request.id)||null};
 if(request.action!=='recipe_delete')return {should_delete:false,response:{success:false,status:400,message:'Неизвестная операция'}};
 if(!Number.isSafeInteger(request.id)||request.id<=0)return {should_delete:false,response:{success:false,status:400,message:'Некорректный рецепт'}};
 const row=own.find(r=>Number(r.id)===request.id);
 if(!row)return {should_delete:false,response:{success:true,deleted:true,id:request.id}};
 return {should_delete:true,actor_id:actor,recipe_id:request.id,snapshot:row};
}
const auth=$('Verify Diary Telegram').first().json;return [{json:prepareRecipeLibrary(auth.actor_id,auth.request,$input.all().map(i=>i.json))}];

function mealNotification(request,response,actorId){
 if(request?.action!=='recipe_add'||response?.success!==true)return null;
 const e=response.entry,actor=Number(actorId);
 if(!e||Number(e.user_id)!==actor||!Number.isSafeInteger(actor)||actor<=0||!Number.isSafeInteger(Number(e.id))||Number(e.id)<=0||e.item_type!=='recipe'||e.deleted_at)return null;
 if(!['weight','calories','protein','fats','carbs'].every(k=>typeof e[k]==='number'&&Number.isFinite(e[k])&&e[k]>=0)||e.weight<=0)return null;
 if(!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(e.date)||!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(e.time))return null;
 const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),n=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(v);
 const date=e.date.slice(8)+'.'+e.date.slice(5,7)+'.'+e.date.slice(0,4);
 return {entry_id:Number(e.id),user_id:actor,message_text:'✅ <b>Приём пищи записан</b>\n\n<b>'+esc(e.item_name)+'</b> · '+n(e.weight)+' г\n'+Math.round(Number(e.calories)).toLocaleString('ru-RU')+' ккал · Б '+n(e.protein)+' г · Ж '+n(e.fats)+' г · У '+n(e.carbs)+' г\n\n'+date+' · '+e.time,diary_url:'https://akuzmin5r-dot.github.io/vilqa-registration/diary/?v=meal-notice-1&date='+e.date+'&entry='+Number(e.id)};
}
const auth=$('Verify Diary Telegram').first().json;const n=mealNotification(auth.request,$input.first().json.response,auth.actor_id);return n?[{json:n}]:[];
